example.code:
graph.add(
  new GPURoseStatistic({
    spatialContext,
    starts,
    ends,
    weights,
    circular: {
      mode: 'axial',
      angleUnit: 'radians',
      origin: 'positive-x-counter-clockwise',
      binCount: ROSE_BIN_COUNT
    },
    output: {summary, bins}
  })
);
// summary: [count, mean angle, resultant length, circular variance, Rayleigh z]
// bins: summed segment length per 10 degree sector
